expected_output:
GET  {}
   → 简单请求，直接发送

POST  {"Content-Type":"text/plain"}
   → 简单请求，直接发送

POST  {"Content-Type":"application/json"}
   → 需预检（先发 OPTIONS）：Content-Type=application/json 不属于三种安全值

PUT  {"Authorization":"Bearer eyJ..."}
   → 需预检（先发 OPTIONS）：方法 PUT 不在安全列表 {GET, HEAD, POST}；自定义头部 Authorization

预检响应必须含 Access-Control-Allow-Origin / -Methods / -Headers；
需携带 Cookie 时还要 Allow-Credentials: true，且 Allow-Origin 不能是 *。
CORS 是「响应头」机制：前端无法通过添加请求头绕过，只能在服务端/网关配置或走开发代理。

code:
const SAFE_METHODS = ['GET', 'HEAD', 'POST'];
const SAFE_HEADERS = ['accept', 'accept-language', 'content-language'];
const SAFE_CONTENT_TYPES = [
  'application/x-www-form-urlencoded',
  'multipart/form-data',
  'text/plain',
];

function preflightReasons(method, headers) {
  const reasons = [];
  if (!SAFE_METHODS.includes(method)) reasons.push('方法 ' + method + ' 不在安全列表 {GET, HEAD, POST}');

  for (const [k, v] of Object.entries(headers)) {
    const lk = k.toLowerCase();
    if (lk === 'content-type') {
      if (!SAFE_CONTENT_TYPES.includes(String(v).toLowerCase())) {
        reasons.push('Content-Type=' + v + ' 不属于三种安全值');
      }
    } else if (!SAFE_HEADERS.includes(lk)) {
      reasons.push('自定义头部 ' + k);
    }
  }
  return reasons;
}

const CASES = [
  ['GET', {}],
  ['POST', { 'Content-Type': 'text/plain' }],
  ['POST', { 'Content-Type': 'application/json' }],
  ['PUT', { 'Authorization': 'Bearer eyJ...' }],
];

for (const [m, h] of CASES) {
  const r = preflightReasons(m, h);
  console.log(m + '  ' + JSON.stringify(h));
  console.log('   → ' + (r.length ? '需预检（先发 OPTIONS）：' + r.join('；') : '简单请求，直接发送'));
  console.log('');
}

console.log('预检响应必须含 Access-Control-Allow-Origin / -Methods / -Headers；');
console.log('需携带 Cookie 时还要 Allow-Credentials: true，且 Allow-Origin 不能是 *。');
console.log('CORS 是「响应头」机制：前端无法通过添加请求头绕过，只能在服务端/网关配置或走开发代理。');
